const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the two points
  const point1 = ee.Geometry.Point([-50.925784, 46.694935]);
  const point2 = ee.Geometry.Point([-58.528990, 46.809436]);

  // Date range for September 19, 2019
  const startDate = '2019-09-19';
  const endDate = '2019-09-20';

  // Function to mask clouds using QA60 band
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudMask = qa.bitwiseAnd(1 << 10).eq(0).and(
                     qa.bitwiseAnd(1 << 11).eq(0));
    return image.updateMask(cloudMask);
  }

  // Get Sentinel-2 collection
  let col1 = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(startDate, endDate)
    .filterBounds(point1)
    .map(maskClouds);

  let col2 = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(startDate, endDate)
    .filterBounds(point2)
    .map(maskClouds);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Point 1 Images: ${size1}, Point 2 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("No images found for one or both points.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composite
  const img1 = col1.median();
  const img2 = col2.median();

  // Calculate brightness (mean of visible bands) as proxy for milkiness
  // Milky water appears brighter/whiter
  const brightness1Image = img1.select(['B2', 'B3', 'B4']).reduce(ee.Reducer.mean());
  const brightness2Image = img2.select(['B2', 'B3', 'B4']).reduce(ee.Reducer.mean());

  // Check pixel counts
  const count1 = await brightness1Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point1,
    scale: 3000,
    maxPixels: 1e9
  }).get('mean').getInfo();

  const count2 = await brightness2Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point2,
    scale: 3000,
    maxPixels: 1e9
  }).get('mean').getInfo();

  console.log(`Valid pixels - Point 1: ${count1}, Point 2: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Get brightness values
  const brightness1 = await brightness1Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point1,
    scale: 3000,
    maxPixels: 1e9
  }).get('mean').getInfo();

  const brightness2 = await brightness2Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point2,
    scale: 3000,
    maxPixels: 1e9
  }).get('mean').getInfo();

  console.log(`Brightness Point 1: ${brightness1}, Point 2: ${brightness2}`);

  if (brightness1 === null || brightness2 === null || 
      isNaN(brightness1) || isNaN(brightness2)) {
    console.log("Calculation failed - invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare: milkier water = higher brightness
  if (brightness1 > brightness2) {
    console.log("Point 1 is more milky (brighter).");
    console.log("<answer>A</answer>");
  } else {
    console.log("Point 2 is more milky or equal.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
